const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Polygon([[
    [148, -39], [154, -39], [154, -28], [148, -28], [148, -39]
  ]], null, false);

  const dateBushfire = ee.Date('2020-01-01');
  const dateBaseline = ee.Date('2019-07-24');
  const collectionName = 'COPERNICUS/S5P/OFFL/L3_AER_AI';
  const band = 'absorbing_aerosol_index';

  // Function to acquire, process, and check data for a given date
  const getMeanAerosol = (date, geometry) => {
    const imageCollection = ee.ImageCollection(collectionName)
      .filterDate(date, date.advance(1, 'day'))
      .filterBounds(geometry);

    // Check if any image is found
    const imageCount = imageCollection.size();
    const image = imageCollection.first();

    return ee.Algorithms.If(
        imageCount.gt(0),
        { // If images exist, process them
            // Filter for high quality pixels (QA value > 0.75)
            const qaMask = image.select('qa_value').gt(0.75);
            const maskedImage = image.select(band).updateMask(qaMask);

            const stats = maskedImage.reduceRegion({
              reducer: ee.Reducer.mean().combine({
                  reducer2: ee.Reducer.count(),
                  sharedInputs: true
              }),
              geometry: geometry,
              scale: 3000,
              maxPixels: 1e9
            });
            // Return mean and pixel count
            return [stats.get(band), stats.get(band + '_count')];
        },
        { // If no images exist, return nulls
            return [ee.Number(null), ee.Number(0)];
        }
    );
  };

  // 2. Data Acquisition & Processing
  const resultsBushfire = ee.List(getMeanAerosol(dateBushfire, region));
  const resultsBaseline = ee.List(getMeanAerosol(dateBaseline, region));

  const meanBushfire = ee.Number(resultsBushfire.get(0));
  const countBushfire = ee.Number(resultsBushfire.get(1));

  const meanBaseline = ee.Number(resultsBaseline.get(0));
  const countBaseline = ee.Number(resultsBaseline.get(1));

  // 3. Retrieve results from the server
  const meanBushfireInfo = meanBushfire.getInfo();
  const countBushfireInfo = countBushfire.getInfo();
  const meanBaselineInfo = meanBaseline.getInfo();
  const countBaselineInfo = countBaseline.getInfo();

  // 4. Validation & Final Answer
  console.log(`Jan 2020 (Bushfire) Mean AI: ${meanBushfireInfo !== null ? meanBushfireInfo.toFixed(3) : 'N/A'}, Pixels: ${countBushfireInfo}`);
  console.log(`Jul 2019 (Baseline) Mean AI: ${meanBaselineInfo !== null ? meanBaselineInfo.toFixed(3) : 'N/A'}, Pixels: ${countBaselineInfo}`);

  if (countBushfireInfo === 0 || countBaselineInfo === 0) {
      console.log("Evidence: No valid pixels were found for one or both dates after quality masking.");
      console.log("B"); // Note: Technically C2, but given S5P's global coverage, this often means no smoke to measure or bad retrieval. In this context, it implies less smoke.
      return;
  }

  if (meanBushfireInfo === null || meanBaselineInfo === null) {
      console.log("Evidence: Calculation failed, reducer returned null.");
      console.log("C3");
      return;
  }

  if (meanBushfireInfo > meanBaselineInfo) {
      console.log("Evidence: The mean Aerosol Index was higher on Jan 1, 2020, indicating more smoke.");
      console.log("A");
  } else {
      console.log("Evidence: The mean Aerosol Index was not higher on Jan 1, 2020.");
      console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err.message);
    if (err.message.includes('Collection.first:')) {
        console.log("Evidence: No images found for the specified date and region.");
        console.log("C1");
    } else {
        console.log("D");
    }
});
